{
  "schema_version": 1,
  "template_id": "browser-journey-qa-analyst",
  "template_version": 2,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the QA role and owner",
      "instructions": "Confirm whether Browser Journey QA Analyst is the primary Crew role or an added capability. Preserve an existing identity and name the QA owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/browser-journey-qa-analyst/SKILL.md exists and browser-journey-qa-analyst is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set the job and exact test scope",
      "instructions": "Record the first job, authorized account and data, expected outcome, build and environment identity, owner, and cutoff time. Minimum input: Approved journey and expected outcome, environment URL, exact build or commit, authorized test account and data, evidence policy, and QA owner."
    },
    {
      "id": "access",
      "title": "Prove the source and runner join",
      "instructions": "Run one approved journey against a pinned build and environment using an authorized test account. Save the attempt ID, required assertion results, recording and console/network artifact IDs, and one failed or blocked step. A successful retry must remain a separate attempt. Record access scope, freshness, and artifact paths. Browser or Playwright runner, CI, issue tracker, and test account vault; a supplied recording and test report support an initial read-only investigation."
    },
    {
      "id": "policy",
      "title": "Verify the role-specific acceptance rule",
      "instructions": "Reproduce one observed failure from the saved attempt on the same build, or mark it unresolved with the missing evidence. Check that a skipped assertion, absent required recording, or blocked account cannot yield pass. Record the customer policy, retention, and approval owner. Missing evidence is not a pass."
    },
    {
      "id": "first_result",
      "title": "Produce a first QA result",
      "instructions": "Use actual authorized evidence to produce An attempt-level journey result with exact build and environment, pass/fail or blocked status, reproduction steps, and linked visual and console/network evidence. A pass requires all required assertions and evidence; skipped, blocked, missing, or stale attempts remain visible and cannot become a pass. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review result and next action",
      "instructions": "Show source-linked facts, unknowns, exact proposed action, owner, and approval boundary. Record the owner decision and corrections."
    },
    {
      "id": "delivery",
      "title": "Choose action and delivery route",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized issue/status updates. Read-only chat completes this choice. Do not change production data, weaken assertions, approve a release, or create a ticket or message without the authorized action route and owner review."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed trigger or schedule. Manual-only completes this choice. On a later run, retain earlier attempts, compare the same journey and build identity rule, and record changed test or environment revisions before claiming a regression was fixed. Test any configured route before activation."
    }
  ],
  "completed_steps": []
}

files.templates/flaky-test-investigator/TEMPLA:
{
  "schema_version": 1,
  "template_id": "flaky-test-investigator",
  "template_version": 2,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the QA role and owner",
      "instructions": "Confirm whether Flaky Test Investigator is the primary Crew role or an added capability. Preserve an existing identity and name the QA owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/flaky-test-investigator/SKILL.md exists and flaky-test-investigator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set the job and exact test scope",
      "instructions": "Record the first job, authorized account and data, expected outcome, build and environment identity, owner, and cutoff time. Minimum input: Canonical test ID and source revision, exact build and environment, fixtures, recent attempt history, retry and concurrency policy, and owner."
    },
    {
      "id": "access",
      "title": "Prove the source and runner join",
      "instructions": "Fetch the canonical test revision and at least one original failed attempt plus its retry for the same build, environment, browser profile, and fixtures. Save each CI run and trace ID; a green summary without the original failure is insufficient. Record access scope, freshness, and artifact paths. CI test history, browser traces, screenshots and video, source repository, and issue tracker; exported attempts support a first read-only analysis."
    },
    {
      "id": "policy",
      "title": "Verify the role-specific acceptance rule",
      "instructions": "Run or inspect a bounded set of isolated attempts under fixed inputs, retain the result distribution, and classify product, test, environment, or unresolved. Reject a proposed wait, quarantine, or assertion change when the cause is still unresolved. Record the customer policy, retention, and approval owner. Missing evidence is not a pass."
    },
    {
      "id": "first_result",
      "title": "Produce a first QA result",
      "instructions": "Use actual authorized evidence to produce An attempt-by-attempt flake investigation with controlled inputs, failure and pass evidence, cause hypotheses, and a reviewable stabilization proposal. A green retry is not proof of stability; report attempt count, result distribution, environment and build identity, and confidence limits. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review result and next action",
      "instructions": "Show source-linked facts, unknowns, exact proposed action, owner, and approval boundary. Record the owner decision and corrections."
    },
    {
      "id": "delivery",
      "title": "Choose action and delivery route",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized issue/status updates. Read-only chat completes this choice. Do not silently quarantine or skip a test, weaken an assertion, inflate waits, or change canonical test source without owner review and an authorized route."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed trigger or schedule. Manual-only completes this choice. Use the same test and build keys to compare new attempts; reopen a prior classification when product or environment evidence contradicts it. Test any configured route before activation."
    }
  ],
  "completed_steps": []
}

