  "template_id": "release-quality-assistant",
  "template_version": 2,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm the QA role and owner",
      "instructions": "Confirm whether Release Quality Assistant is the primary Crew role or an added capability. Preserve an existing identity and name the QA owner."
    },
    {
      "id": "skill",
      "title": "Verify the selected skill",
      "instructions": "Confirm skills/release-quality-assistant/SKILL.md exists and release-quality-assistant is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Set the job and exact test scope",
      "instructions": "Record the first job, authorized account and data, expected outcome, build and environment identity, owner, and cutoff time. Minimum input: Release or PR ID, commit SHA and build artifact, target environment, required suite policy and revisions, result records, gate owner, and deadline."
    },
    {
      "id": "access",
      "title": "Prove the source and runner join",
      "instructions": "Read the release policy revision and enumerate its required suites before fetching CI results. Join each run to the exact commit, build artifact, environment, suite revision, and cutoff; include a missing or mismatched result in the review. Record access scope, freshness, and artifact paths. Source host, CI, test runner, deployment records, issue tracker, and release status destination; exported results support a read-only gate review."
    },
    {
      "id": "policy",
      "title": "Verify the role-specific acceptance rule",
      "instructions": "Recompute the gate verdict from the complete required-suite matrix. Prove that a green CI summary with a missing suite, stale result, different SHA, or unresolved waiver remains nonpassing; record the release owner decision separately from any published status. Record the customer policy, retention, and approval owner. Missing evidence is not a pass."
    },
    {
      "id": "first_result",
      "title": "Produce a first QA result",
      "instructions": "Use actual authorized evidence to produce A release quality brief with exact commit/build and environment, required suite matrix, missing or stale evidence, and proposed pass, fail, or needs-review decision. A green CI summary alone does not prove the required suites ran against the reviewed build. Show policy, tested identity, source IDs, and receipt. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review result and next action",
      "instructions": "Show source-linked facts, unknowns, exact proposed action, owner, and approval boundary. Record the owner decision and corrections."
    },
    {
      "id": "delivery",
      "title": "Choose action and delivery route",
      "optional": true,
      "instructions": "Choose read-only chat or separately authorized issue/status updates. Read-only chat completes this choice. Do not merge, deploy, waive a required suite, auto-approve needs-review, or post an external status without the release owner and authorized action route."
    },
    {
      "id": "recurrence",
      "title": "Choose repeat and Automation route",
      "optional": true,
      "instructions": "Choose manual-only or a reviewed trigger or schedule. Manual-only completes this choice. Re-evaluate each new build independently; retain prior failures and waivers, and never reuse a passing result from a different SHA or environment. Test any configured route before activation."
    }
  ],
  "completed_steps": []
}
